import{_ as i,o,c as s,a2 as t,j as a,t as n,a as l}from"./chunks/framework.BXm-Zw-h.js";const m=JSON.parse('{"title":"Notebook Basics","description":"","frontmatter":{},"headers":[],"relativePath":"notebook-basics.md","filePath":"notebook-basics.md","lastUpdated":null}'),d={name:"notebook-basics.md"};function r(c,e,h,p,g,k){return o(),s("div",null,[e[2]||(e[2]=t(`<h1 id="Notebook-Basics" tabindex="-1">Notebook Basics <a class="header-anchor" href="#Notebook-Basics" aria-label="Permalink to &quot;Notebook Basics {#Notebook-Basics}&quot;">​</a></h1><h2 id="Cell-types" tabindex="-1">Cell types <a class="header-anchor" href="#Cell-types" aria-label="Permalink to &quot;Cell types {#Cell-types}&quot;">​</a></h2><p>There are four kinds:</p><ul><li><p><strong>Code cells</strong> evaluate Julia. The last expression&#39;s value renders below, along with stdout and any rich display (images, ECharts, tables, LaTeX).</p></li><li><p><strong>Markdown cells</strong> render GitHub-flavored markdown with LaTeX math and double-brace interpolation of Julia values. GFM tables work, as do <code>!!! note &quot;Title&quot;</code> admonitions; the category is free-form, so a notebook can coin its own.</p></li><li><p><strong>Web cells</strong> hold HTML, CSS and JS in their own panes, for building an interface that talks to Julia. See <a href="./frontend-extensions">Front-end Extensions</a>.</p></li><li><p><strong>Tool cells</strong> hold an <code>@tool name(...)</code> call, defining a tool the <a href="./agent">agent</a> can call. They are never swept up by an automatic run, so reopening a notebook does not re-fire one.</p></li></ul><p>The cell header shows a button for each kind the cell is <em>not</em> (<code>{·}</code> code, <code>&lt;/&gt;</code> web, <code>⌁</code> tool, <code>M↓</code> markdown). In command mode, <code>y</code> / <code>m</code> / <code>w</code> convert to code, markdown and web.</p><p>A code cell shows an always-on editor with tree-based Julia highlighting (CodeMirror 6 + the Lezer Julia grammar), the run button, timing, and state badge:</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/editor-highlighting.png" alt=""></p><h2 id="Command-mode-vs.-edit-mode" tabindex="-1">Command mode vs. edit mode <a class="header-anchor" href="#Command-mode-vs.-edit-mode" aria-label="Permalink to &quot;Command mode vs. edit mode {#Command-mode-vs.-edit-mode}&quot;">​</a></h2><p>KaimonSlate uses a Jupyter-style two-mode model:</p><ul><li><p><strong>Command mode</strong> — the cell has an accent ring and single keys act on it.</p></li><li><p><strong>Edit mode</strong> — focus is inside the editor (green ring); <code>Esc</code> returns to command mode.</p></li></ul><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>↑</code>/<code>k</code>, <code>↓</code>/<code>j</code></td><td style="text-align:right;">move selection</td></tr><tr><td style="text-align:right;"><code>⇧↑</code> / <code>⇧↓</code> (also <code>⇧K</code> / <code>⇧J</code>)</td><td style="text-align:right;">extend the selection to the cell above / below</td></tr><tr><td style="text-align:right;"><code>⌥↑</code> / <code>⌥↓</code></td><td style="text-align:right;"><strong>move the cell</strong> up/down</td></tr><tr><td style="text-align:right;"><code>Esc</code></td><td style="text-align:right;">collapse a multi-selection back to one cell</td></tr><tr><td style="text-align:right;"><code>⏎</code></td><td style="text-align:right;">enter edit mode</td></tr><tr><td style="text-align:right;"><code>a</code> / <code>b</code></td><td style="text-align:right;">add cell above / below</td></tr><tr><td style="text-align:right;"><code>c</code> / <code>x</code> / <code>v</code></td><td style="text-align:right;">copy / cut / paste cell(s)</td></tr><tr><td style="text-align:right;"><code>m</code> / <code>y</code> / <code>w</code></td><td style="text-align:right;">to markdown / to code / to <a href="./frontend-extensions">web</a></td></tr><tr><td style="text-align:right;"><code>dd</code></td><td style="text-align:right;">delete cell</td></tr><tr><td style="text-align:right;"><code>⇧M</code></td><td style="text-align:right;">merge with the cell below</td></tr></tbody></table><p>Select several cells with shift-click (a range) or ⌘/Ctrl-click (toggle one), as well as the ⇧-arrow keys. Delete, cut, copy and the type-toggle keys then act on the whole selection, and a floating chip shows how many are selected. The cell clipboard is shared across notebook tabs.</p><p>You can also reorder with the mouse: drag the <strong>⠿</strong> grip in a cell&#39;s header and a drop line shows where it will land, or use the header&#39;s ↑/↓ buttons to move it one place.</p><p>In edit mode:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>⇧⏎</code></td><td style="text-align:right;">run (or commit a markdown/bind cell)</td></tr><tr><td style="text-align:right;"><code>⌘⇧⏎</code> / <code>Ctrl⇧⏎</code></td><td style="text-align:right;">run and open a fresh cell below</td></tr><tr><td style="text-align:right;"><code>⌘⇧-</code> / <code>Ctrl⇧-</code></td><td style="text-align:right;">split the cell at the cursor</td></tr><tr><td style="text-align:right;"><code>⇥</code></td><td style="text-align:right;">completion (Julia REPL completions + cell-local bindings)</td></tr></tbody></table><p>Notebook-wide:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>⌘↵</code></td><td style="text-align:right;">run stale cells</td></tr><tr><td style="text-align:right;"><code>⌘K</code> / <code>⌘⇧K</code></td><td style="text-align:right;">command palette / docs search</td></tr><tr><td style="text-align:right;"><code>⌘⇧A</code></td><td style="text-align:right;">agent panel</td></tr><tr><td style="text-align:right;"><code>⌘⇧F</code></td><td style="text-align:right;">controls palette</td></tr><tr><td style="text-align:right;"><code>⌘⇧L</code></td><td style="text-align:right;">table of contents</td></tr><tr><td style="text-align:right;"><code>⌘⇧G</code></td><td style="text-align:right;">dependency graph</td></tr><tr><td style="text-align:right;"><code>⌘⇧S</code></td><td style="text-align:right;">scratchpad</td></tr><tr><td style="text-align:right;"><code>⌘Z</code> / <code>⌘⇧Z</code></td><td style="text-align:right;">undo / redo structural changes</td></tr></tbody></table><h2 id="Running-cells" tabindex="-1">Running cells <a class="header-anchor" href="#Running-cells" aria-label="Permalink to &quot;Running cells {#Running-cells}&quot;">​</a></h2><p>Run a single cell with <strong>⇧⏎</strong>, or press <strong>⌘⏎</strong> (<strong>Ctrl⏎</strong>) to recompute every stale cell. The same action is in the command palette as <em>Run stale cells</em>. The kernel dot in the top bar breathes while a computation is in flight.</p><h3 id="Stopping-a-run" tabindex="-1">Stopping a run <a class="header-anchor" href="#Stopping-a-run" aria-label="Permalink to &quot;Stopping a run {#Stopping-a-run}&quot;">​</a></h3><p>A run in flight can be interrupted. That leaves the namespace intact, so everything computed so far is still there. <strong>⟲ Restart worker</strong> is the heavier option: it discards the run and the namespace with it.</p><h3 id="When-a-run-gets-stuck" tabindex="-1">When a run gets stuck <a class="header-anchor" href="#When-a-run-gets-stuck" aria-label="Permalink to &quot;When a run gets stuck {#When-a-run-gets-stuck}&quot;">​</a></h3><p>A supervisor sweeps every few seconds and raises a badge in the top bar when something looks wrong: amber for a warning, red for something critical. Clicking it opens a panel naming each alert, a stalled kernel or a runaway loop, with the recovery action for that alert (stop the run, or restart the worker).</p><h2 id="The-scratchpad" tabindex="-1">The scratchpad <a class="header-anchor" href="#The-scratchpad" aria-label="Permalink to &quot;The scratchpad {#The-scratchpad}&quot;">​</a></h2><p><strong>☰ → 🧪 Scratchpad</strong> (⌘⇧S) opens a panel where you can run Julia in the notebook&#39;s own kernel without creating a cell or touching the <code>.jl</code>. Results stream in with a timestamp, 🧹 clears them, and the 🧪 pill in the top bar lights up while something is running there.</p><p>It is the place for a quick check that is not part of the document. The <a href="./agent">agent</a>&#39;s <code>slate_eval</code> runs in the same scratchpad.</p><h2 id="Opening-a-cold-notebook" tabindex="-1">Opening a cold notebook <a class="header-anchor" href="#Opening-a-cold-notebook" aria-label="Permalink to &quot;Opening a cold notebook {#Opening-a-cold-notebook}&quot;">​</a></h2><p>The first open of a notebook whose packages are not yet precompiled shows a banner reading <em>Precompiling k/N · &lt;package&gt;</em>, with elapsed time and a collapsible build log. This is one-time; later opens are fast, and you can keep editing while it runs.</p><p>Installing a package mid-session is different: that shows a blocking overlay, because the notebook is paused while its environment resolves and precompiles.</p><p>A notebook can also open <strong>inactive</strong>, showing its stored results with no worker behind it. See <a href="/KaimonSlate.jl/dev/getting-started#The-front-page">the front page</a>.</p><h2 id="Quiet-cells" tabindex="-1">Quiet cells <a class="header-anchor" href="#Quiet-cells" aria-label="Permalink to &quot;Quiet cells {#Quiet-cells}&quot;">​</a></h2><p>A code cell whose last non-comment line ends in <code>;</code> suppresses display of the value (stdout and explicit <code>display()</code> still show) — handy for setup cells.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">big </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># no 1000×1000 dump</span></span></code></pre></div><h2 id="Markdown-interpolation" tabindex="-1">Markdown interpolation <a class="header-anchor" href="#Markdown-interpolation" aria-label="Permalink to &quot;Markdown interpolation {#Markdown-interpolation}&quot;">​</a></h2><p>Inside a markdown cell, a double-brace <code>expr</code> block splices a Julia value into the rendered output:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mean: {{ round(mean(data); digits=2) }}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ echart(spec) }}          &lt;!-- an interactive chart --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ slate_table(df) }}       &lt;!-- an interactive table --&gt;</span></span></code></pre></div><p>Scalars render inline; images, charts, and tables render as blocks. Interpolation works inside math (<code>$…$</code>) too.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/markdown.png" alt=""></p><h2 id="Images-and-clips" tabindex="-1">Images and clips <a class="header-anchor" href="#Images-and-clips" aria-label="Permalink to &quot;Images and clips {#Images-and-clips}&quot;">​</a></h2><p>An image alone in its paragraph is treated as a figure and centred; one sitting inside a run of prose stays inline where you put it. An attribute block directly after the image (no space, as in Pandoc/Quarto) overrides how it is drawn:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">A phase portrait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">plot.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){width=300}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Logo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">logo.svg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){width=40% align=right}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Detail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">detail.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){.zoomable #fig-detail title=&quot;click to enlarge&quot;}</span></span></code></pre></div>`,41)),a("p",null,[e[0]||(e[0]=t("<code>width</code>/<code>height</code> take a bare number as pixels (<code>300</code> → <code>300px</code>) or any CSS length or percentage; <code>align</code> is <code>left</code>, <code>right</code>, or <code>center</code>; <code>.name</code> adds a class, <code>#name</code> sets an id. The same block works on a <code>&lt;video&gt;</code> or <code>&lt;audio&gt;</code> you dropped into the cell, and on an interpolated ",24)),a("code",null,n(),1),e[1]||(e[1]=l(" image. Sizes carry into the HTML export and the PDF; unrecognised keys are dropped rather than emitted.",-1))]),e[3]||(e[3]=t('<h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><p>Tab-completion uses Julia&#39;s REPL completions against the live kernel <strong>plus</strong> the cell&#39;s own local bindings (assignments, loop/comprehension variables, function parameters) so names complete even before the cell has run. The popup carries a docstring preview, and method completions insert tab-through argument placeholders. LaTeX/emoji shortcuts work — type <code>\\pi</code>⇥ → <code>π</code>.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/completion.png" alt=""></p><h2 id="Renaming-cells" tabindex="-1">Renaming cells <a class="header-anchor" href="#Renaming-cells" aria-label="Permalink to &quot;Renaming cells {#Renaming-cells}&quot;">​</a></h2><p>Cell ids are header-safe labels. Double-click a cell&#39;s id to rename it; renames are tracked as renames in <a href="./history">history</a>, and dependencies (which are by id) are rebuilt.</p>',5))])}const b=i(d,[["render",r]]);export{m as __pageData,b as default};
